// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v2/administrations", wrapper.ListAdministrations)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v2/administrations", wrapper.CreateAdministration)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v2/administrations/{id}", wrapper.GetAdministration)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v2/administrations/{id}/favorite", wrapper.UnfavoriteAdministration)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v2/administrations/{id}/favorite", wrapper.FavoriteAdministration)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/onboarding/options", wrapper.OnboardingOptions)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/onboarding/company_search", wrapper.CompanySearch)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/onboarding/address_lookup", wrapper.AddressLookup)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/resources/{id}", wrapper.LocateResource)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/providers", wrapper.AuthProviders)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/register", wrapper.Register)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/password_reset/request", wrapper.RequestPasswordReset)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/password_reset/confirm", wrapper.ConfirmPasswordReset)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/me", wrapper.CurrentUser)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/google/start", wrapper.GoogleStart)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/google/callback", wrapper.GoogleCallback)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/lm2/start", wrapper.Lm2Start)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/auth/lm2/callback/{state}", wrapper.Lm2Callback)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/user/tokens", wrapper.ListTokens)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/user/tokens", wrapper.CreateToken)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/user/tokens/{id}", wrapper.DeleteToken)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/instance/settings/test_email", wrapper.SendTestEmail)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/instance/settings", wrapper.InstanceSettings)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/instance/settings", wrapper.UpdateInstanceSettings)
	})

	return r
}
